import type { Preset, PresetFactorView } from './types';
import type { KnownCredences, KnownFactorId, KnownSubCredences, KnownSubfactorId } from './ids';

/**
 * ============================================================================
 *  BELIEF PRESETS — public figures & organizations.
 * ============================================================================
 * Each preset maps an entity's publicly-stated views onto the model's factors.
 * Fidelity is reported PER FACTOR, not as one overall number: `factors[id]` has a
 * short `note`, an `accuracy` (how directly the public record pins THAT factor for
 * THAT entity, 0–1), and `refs` — 1-based indices into the entity's `references`
 * list (rendered as superscripts). Accuracy bands:
 *   0.85–1.0  explicit / quantified on record
 *   0.55–0.8  clear qualitative position
 *   0.3–0.5   inferred from adjacent statements
 *   <0.3      little/no record (refs usually empty)
 *
 * These are one editor's reading of public statements (per a 2024–2025 sourcing
 * pass), NOT the entities' own per-factor numbers except where directly quoted.
 *
 * Coherence rule: deceptive alignment is a subclass of unsolved alignment (a system
 * that fakes its evaluations IS an alignment failure), so each preset's
 * P(deception=deceptive) is capped at its P(alignmentInTime=no). Stated deception
 * concerns above that bound are read as "conditional on failure, it's deceptive"
 * and capped — otherwise the two failure modes would double-count.
 *
 * Odds-scale granularity: probabilities near 0/1 are stated to THREE decimals for
 * the extremists (Yampolskiy, Yudkowsky), because on the odds scale 0.99 vs 0.995
 * vs 0.999 are different claims (100:1 / 200:1 / 1000:1) and a 0.01 floor on any
 * survival route caps implied doom at ~100:1 no matter what else is set. Three
 * decimals is a deliberate SATISFICING stop: professed numbers like Yampolskiy's
 * "99.999999%" are read as directional rhetoric, not literal credences, and a
 * 1,728-cell shared-value model cannot meaningfully resolve millionths anyway.
 * With these, his model-implied doom is ~99.7% (net) / ~99.96% (independence) —
 * hundreds-to-thousands to one against, which preserves his ordinal extremity
 * (far beyond every other preset) without pretending to precision the model
 * doesn't have.
 *
 * `subCredences` (the alignment deep-dive: legibility, value spec, corrigibility,
 * oversight scaling + the four research-area maturity forecasts) come from a
 * dedicated 2026 sourcing pass (per-subfactor notes/accuracy/refs in `factors`).
 * Their CONFIDENCE is calibrated against each preset's stated top-level numbers
 * (accuracy-damped sharpening/tilt: well-sourced positions barely move, vague ones
 * are pinned by what the entity actually states), so the DERIVED tractability /
 * alignment-in-time track the stated credences closely — extremes included
 * (Yampolskiy derives nearImpossible ≈ 0.96). Test-enforced tolerances; the few
 * remaining tractability gaps (Hinton, Kokotajlo, Sutskever) all have the same
 * shape — stated hard-but-doable numbers vs pessimistic specific positions on
 * oversight/corrigibility — and are left visible on purpose.
 * offense/defense balance is rarely addressed head-on and is usually the weakest
 * cell. Corrections welcome: edit this file. Ordered roughly most-pessimistic →
 * most-skeptical.
 * ============================================================================
 */

/**
 * Content-typed preset: full credences over every known factor AND every known
 * alignment subfactor — a typo'd state, a missing (sub)factor, or a stray key is a
 * compile error, and adding one in ids.ts forces every preset to take a position on
 * it. Factor notes are keyed likewise (subfactors included).
 */
type KnownPreset = Omit<Preset, 'credences' | 'subCredences' | 'factors'> & {
  credences: KnownCredences;
  subCredences: KnownSubCredences;
  factors: Partial<Record<KnownFactorId | KnownSubfactorId, PresetFactorView>>;
};

